// Keep only successful transcript rows and shape what the AI brief needs.
// Dataset rows (see actor README): success = { videoId, url, title, channel, language,
// isAutoGenerated, availableLanguages, segments[{start,dur,text}], text, srt };
// failure = { url, videoId?, error, errorType } — failed rows are never charged.
const rows = $input.all().map(i => i.json);
const good = rows.filter(r => !r.error && r.text);

if (!good.length) {
  const why = rows.map(r => (r.errorType || 'UNKNOWN') + ': ' + (r.error || 'no transcript text')).join(' | ')
    || 'actor returned no items';
  throw new Error('No transcript delivered (' + why + '). Failed videos are not charged.');
}

const MAX_CHARS = 12000;

return good.map(r => {
  // Weave [mm:ss] markers (one per ~60s) into the text so the model cites real positions.
  let excerpt = '';
  if (Array.isArray(r.segments) && r.segments.length) {
    let nextMark = 0;
    for (const s of r.segments) {
      if (typeof s.start === 'number' && s.start >= nextMark) {
        const m = Math.floor(s.start / 60);
        const sec = String(Math.floor(s.start % 60)).padStart(2, '0');
        excerpt += '\n[' + m + ':' + sec + '] ';
        nextMark = (m + 1) * 60;
      }
      excerpt += s.text + ' ';
      if (excerpt.length > MAX_CHARS) break;
    }
  } else {
    excerpt = r.text || '';
  }
  const truncated = excerpt.length > MAX_CHARS;
  excerpt = excerpt.slice(0, MAX_CHARS).trim();

  const last = Array.isArray(r.segments) && r.segments.length ? r.segments[r.segments.length - 1] : null;
  const lengthMinutes = last ? Math.max(1, Math.round(((last.start || 0) + (last.dur || 0)) / 60)) : null;

  return { json: {
    videoId: r.videoId,
    url: r.url,
    title: r.title || r.videoId || 'Untitled video',
    channel: r.channel || 'Unknown channel',
    language: r.language,
    isAutoGenerated: r.isAutoGenerated === true,
    lengthMinutes,
    truncated,
    transcriptExcerpt: excerpt,
  } };
});
